const today=()=>new Intl.DateTimeFormat('en-CA',{timeZone:'Asia/Jakarta'}).format(new Date());
const ym=()=>today().slice(0,7); const first=(m:string)=>`${m}-01`; const last=(m:string)=>{const [y,n]=m.split('-').map(Number);return `${y}-${String(n).padStart(2,'0')}-${String(new Date(Date.UTC(y,n,0)).getUTCDate()).padStart(2,'0')}`}; const move=(m:string,x:number)=>{const [y,n]=m.split('-').map(Number),d=new Date(Date.UTC(y,n-1+x,1));return `${d.getUTCFullYear()}-${String(d.getUTCMonth()+1).padStart(2,'0')}`};
type Space={id:string,name:string,type:'personal'|'family',owner_user_id:string,status:string}; type Member={id:string,space_id:string,user_id:string,role:'owner'|'member',status:string}; type Cat={id:string,name:string,type:'income'|'expense'}; type Tx={id:string,type:'income'|'expense',amount:number,category_id:string,transaction_date:string,transaction_time:string|null,note:string|null,status:'confirmed'|'voided',version:number}; type Debt={id:string,direction:'payable'|'receivable',party_name:string,original_amount:number,due_date:string|null,status:string,note:string|null}; type Bill={id:string,name:string,default_amount:number,frequency:string,next_due_date:string,reminder_days_before:number,status:string};
export default function App(){const [session,setSession]=useState<any>(),[ready,setReady]=useState(false),[guest,setGuest]=useState(false),[spaces,setSpaces]=useState<Space[]>([]),[space,setSpace]=useState<Space|null>(null),[member,setMember]=useState<Member|null>(null),[notice,setNotice]=useState(''),[pendingInvite,setPendingInvite]=useState<string>(()=>normalizeInvite(localStorage.getItem(INVITE_STORAGE_KEY))||normalizeInvite(new URLSearchParams(window.location.search).get('invite'))); useEffect(()=>{const fromUrl=normalizeInvite(new URLSearchParams(window.location.search).get('invite'));if(fromUrl){localStorage.setItem(INVITE_STORAGE_KEY,fromUrl);setPendingInvite(fromUrl);const url=new URL(window.location.href);url.searchParams.delete('invite');window.history.replaceState({},'',url.toString())}db.auth.getSession().then(({data})=>setSession(data.session)).finally(()=>setReady(true));const {data}=db.auth.onAuthStateChange((_e,s)=>setSession(s));return()=>data.subscription.unsubscribe()},[]); useEffect(()=>{if(session)void load();else{setSpaces([]);setSpace(null)}},[session]); async function migrateGuestData(personalSpaceId:string){
  if(localStorage.getItem('rupkas.guest.migrated')==='1')return;
  const raw=localStorage.getItem('rupkas.guest'); if(!raw)return;
  let rows:any[]=[]; try{rows=JSON.parse(raw)}catch{return}
  if(!rows.length)return;
  const {data:categories}=await db.from('categories').select('id,type').eq('space_id',personalSpaceId).eq('is_active',true);
  const categoryByType={expense:(categories??[]).find((x:any)=>x.type==='expense')?.id,income:(categories??[]).find((x:any)=>x.type==='income')?.id};
  for(const r of rows){
    const type=(r.type==='income'?'income':'expense') as 'income'|'expense';
    const categoryId=categoryByType[type];
    if(!categoryId)return;
    const {error}=await db.rpc('create_transaction',{p_space_id:personalSpaceId,p_type:type,p_amount:Number(r.amount),p_category_id:categoryId,p_transaction_date:String(r.date||today()),p_transaction_time:null,p_source_text:'guest_migration',p_note:[r.category,r.note].filter(Boolean).join(' · ')||null,p_client_operation_id:r.id});
    if(error)return;
  }
  localStorage.removeItem('rupkas.guest');localStorage.setItem('rupkas.guest.migrated','1');
  setNotice('Data Guest berhasil dipindahkan ke Personal Space.');
}
async function load(){setReady(false);const {data:m,error}=await db.from('space_members').select('id,space_id,user_id,role,status').eq('user_id',session.user.id).eq('status','active');if(error){setNotice(error.message);setReady(true);return}const ids=(m??[]).map((x:any)=>x.space_id);const {data:s,error:e}=ids.length?await db.from('spaces').select('id,name,type,owner_user_id,status').in('id',ids).eq('status','active').order('name'):{data:[],error:null as any};if(e){setNotice(e.message);setReady(true);return}const list=(s??[]) as Space[],pick=list.find(x=>x.id===localStorage.getItem('rupkas.space'))||list[0]||null;setSpaces(list);setSpace(pick);setMember(((m??[]).find((x:any)=>x.space_id===pick?.id)||null) as Member|null);
    if(list.some((x)=>x.type==='personal')){void migrateGuestData(list.find((x)=>x.type==='personal')!.id)}
    setReady(true)} if(!ready)return <div className="center"><div className="spinner"/>Memuat Rupkas…</div>; if(!session&&!guest)return <Auth notice={notice} setNotice={setNotice} guest={()=>setGuest(true)} inviteCode={pendingInvite}/>; if(guest)return <Guest back={()=>setGuest(false)}/>; if(!space)return <Onboarding notice={notice} setNotice={setNotice} refresh={load} initialInvite={pendingInvite}/>; return <Shell session={session} spaces={spaces} space={space} member={member} notice={notice} setNotice={setNotice} refresh={load} pendingInvite={pendingInvite} onInviteConsumed={()=>{localStorage.removeItem(INVITE_STORAGE_KEY);setPendingInvite('')}}/>}
function Auth({notice,setNotice,guest,inviteCode}:{notice:string,setNotice:(s:string)=>void,guest:()=>void,inviteCode:string}){const [signup,setSignup]=useState(false),[email,setEmail]=useState(''),[password,setPassword]=useState(''),[name,setName]=useState(''),[busy,setBusy]=useState(false),[captchaToken,setCaptchaToken]=useState('');const captchaRef=useRef<any>(null);function switchMode(next:boolean){setSignup(next);setCaptchaToken('');captchaRef.current?.reset()}async function go(e:FormEvent){e.preventDefault();setBusy(true);setNotice('');try{if(TURNSTILE_SITE_KEY&&!captchaToken){setNotice('Verifikasi keamanan diperlukan.');return}const options=TURNSTILE_SITE_KEY?{captchaToken}:undefined;if(signup){const {data,error}=await db.auth.signUp({email:email.trim(),password,options:{data:{display_name:name.trim()},...(options||{})}});if(error)throw error;if(!data.session)setNotice('Akun dibuat. Cek email untuk verifikasi.')}else{const {error}=await db.auth.signInWithPassword({email:email.trim(),password,options});if(error)throw error}}catch(e:any){setNotice(e.message||'Autentikasi gagal')}finally{captchaRef.current?.reset();setCaptchaToken('');setBusy(false)}}return <main className="auth"><section className="panel auth-panel"><div className="logo">R</div><p className="eyebrow">RUPKAS</p><h1>Rupiah Kas, lebih jelas.</h1><p className="muted">Keuangan personal dan keluarga, satu ruang.</p>{inviteCode&&<div className="invite-pending-card"><Icon name="group_add"/><div><strong>Undangan Family terdeteksi</strong><span>Masuk atau daftar seperti biasa. Setelah masuk, Rupkas akan menawarkan untuk bergabung ke Family Space.</span></div></div>}<div className="seg"><button type="button" className={!signup?'active':''} onClick={()=>switchMode(false)}>Masuk</button><button type="button" className={signup?'active':''} onClick={()=>switchMode(true)}>Daftar</button></div><form onSubmit={go}>{signup&&<label>Nama<input value={name} onChange={e=>setName(e.target.value)} required autoComplete="name"/></label>}<label>Email<input type="email" value={email} onChange={e=>setEmail(e.target.value)} required autoComplete="email"/></label><label>Password<input type="password" value={password} onChange={e=>setPassword(e.target.value)} minLength={8} required autoComplete={signup?'new-password':'current-password'}/></label>{TURNSTILE_SITE_KEY&&<div className="captcha-box"><Turnstile ref={captchaRef} siteKey={TURNSTILE_SITE_KEY} onSuccess={(token)=>setCaptchaToken(token)} onExpire={()=>setCaptchaToken('')} onError={()=>setCaptchaToken('')} refreshExpired="auto"/><span>Verifikasi keamanan untuk mencegah akun bot dan penyalahgunaan.</span></div>}{notice&&<div className="notice">{notice}</div>}<button className="primary wide" disabled={busy||Boolean(TURNSTILE_SITE_KEY&&!captchaToken)}>{busy?'Memproses…':signup?'Buat akun':'Masuk'}</button></form><button className="link" onClick={guest}>Coba guest/local mode</button></section></main>}

function Onboarding({notice,setNotice,refresh,initialInvite}:{notice:string,setNotice:(s:string)=>void,refresh:()=>Promise<void>,initialInvite:string}){const [name,setName]=useState(''),[code,setCode]=useState(initialInvite),[join,setJoin]=useState(!!initialInvite),[busy,setBusy]=useState(false);async function go(){setBusy(true);try{const {error}=await db.rpc(join?'claim_invitation':'create_family_space',join?{p_code:code.trim()}:{p_name:name.trim()});if(error)throw error;if(join){localStorage.removeItem(INVITE_STORAGE_KEY)}await refresh()}catch(e:any){setNotice(e.message||'Gagal')}finally{setBusy(false)}}return <main className="auth"><section className="panel auth-panel"><div className="logo">R</div><p className="eyebrow">ONBOARDING</p><h1>{initialInvite?'Undangan Family':'Ruang belum aktif.'}</h1>{initialInvite&&<div className="invite-pending-card"><Icon name="group_add"/><div><strong>Undangan Family terdeteksi</strong><span>Kode sudah diisi dari link undangan. Periksa lalu gabung.</span></div></div>}<div className="seg"><button className={!join?'active':''} onClick={()=>setJoin(false)}>Buat keluarga</button><button className={join?'active':''} onClick={()=>setJoin(true)}>Gabung</button></div><label>{join?'Kode invitation':'Nama Family Space'}<input value={join?code:name} onChange={e=>join?setCode(e.target.value.toUpperCase()):setName(e.target.value)} placeholder={join?'KODE':'Keluarga'}/></label>{notice&&<div className="notice">{notice}</div>}<button className="primary wide" disabled={busy||!(join?code:name).trim()} onClick={()=>void go()}>{busy?'Memproses…':join?'Gabung':'Buat Family Space'}</button></section></main>}

function PendingInviteBanner({code,notice,refresh,onConsumed}:{code:string,notice:(s:string)=>void,refresh:()=>Promise<void>,onConsumed:()=>void}){const [busy,setBusy]=useState(false);if(!code)return null;async function join(){setBusy(true);const {data,error}=await db.rpc('claim_invitation',{p_code:code});if(error){notice(error.message);setBusy(false);return}if(data?.space_id)localStorage.setItem('rupkas.space',data.space_id);onConsumed();await refresh();notice('Berhasil bergabung ke Family Space.');setBusy(false)}return <section className="invite-banner"><div className="invite-banner-icon"><Icon name="group_add"/></div><div className="invite-banner-copy"><strong>Anda menerima undangan Family</strong><span>Kode undangan sudah dibaca dari link. Bergabung sekarang tanpa perlu mengetik ulang.</span></div><button className="primary" disabled={busy} onClick={()=>void join()}><Icon name="group_add"/>{busy?'Memproses…':'Gabung Family'}</button></section>}
